for english, text in pairs(language.postMarks) do language.postMarks[english] = text:upper() end
for english, text in pairs(dictionary) do language.upper[english:upper()] = text:upper() end

local MONTHS = { Jan = "янв", Feb = "фев", Mar = "мар", Apr = "апр", May = "мая", Jun = "июн",
  Jul = "июл", Aug = "авг", Sep = "сен", Oct = "окт", Nov = "ноя", Dec = "дек" }

local COINS = { g = "з", s = "с", c = "м" }

function language.TransformVisible(s, text)
  s = s:gsub("\194\183", "\226\128\162"):gsub("\226\128\186", "\194\187")
  if text:find("/fl ", 1, true) or text:find("Примеры", 1, true) then return s end
  s = s:gsub("(%d+)h%s+(%d+)m%f[%A]", "%1 ч %2 мин"):gsub("(%d+)m%s+(%d+)s%f[%A]", "%1 мин %2 с")
  s = s:gsub("%f[%w](%d+)([gsc])%f[%A]", function(n, unit) return n .. COINS[unit] end)
  return (s:gsub("%f[%a](%a%a%a) (%d%d?)%f[%D]", function(month, day)
    return MONTHS[month] and (tonumber(day) .. " " .. MONTHS[month]) or (month .. " " .. day)
  end))
end

function language.FormatElapsed(seconds)
  if seconds < 60 then return ("%d с"):format(seconds) end
  return ("%d мин %d с"):format(math.floor(seconds / 60), seconds % 60)
end

ns.RegisterLocale("ruRU", language)
